=== graphic/tests/graphics/bar-chart.js
// bar-chart — road map 10 §5k 4: `values` as a comma-separated string, bars
// growing in sequence, labels.
export const meta = {
  name: "Bar chart",
  durationInFrames: 150,
};

export const schema = {
  values: { type: "string", default: "12, 19, 7, 24, 15, 30" },
  labels: { type: "string", default: "Mon, Tue, Wed, Thu, Fri, Sat" },
  title:  { type: "string", default: "Sessions per day" },
  color:  { type: "color",  default: "#2d7ff9" },
};

export function render(frame, props, ctx) {
  const u = ctx.height / 1080;
  const values = props.values.split(",").map((v) => Number(v.trim())).filter((v) => isFinite(v));
  const labels = props.labels.split(",").map((l) => l.trim());
  const top = Math.max(1, ...values);
  const chartLeft = 200 * u;
  const chartRight = ctx.width - 200 * u;
  const base = ctx.height - 200 * u;
  const tall = ctx.height - 460 * u;
  const slot = (chartRight - chartLeft) / Math.max(1, values.length);
  const barWidth = slot * 0.62;
  let bars = "";
  values.forEach((v, i) => {
    const grow = spring({ frame: frame - 10 - i * 8, fps: ctx.fps, damping: 13 });
    const h = (v / top) * tall * grow;
    const x = chartLeft + slot * i + (slot - barWidth) / 2;
    const shown = Math.round(v * Math.min(1, Math.max(0, grow)));
    bars += `<rect x="${x}" y="${base - h}" width="${barWidth}" height="${h}" fill="${props.color}"/>`;
    bars += `<text x="${x + barWidth / 2}" y="${base - h - 16 * u}" text-anchor="middle" font-family="IBM Plex Mono"
                   font-size="${34 * u}" fill="#ffffff" opacity="${Math.min(1, Math.max(0, grow))}">${shown}</text>`;
    bars += `<text x="${x + barWidth / 2}" y="${base + 56 * u}" text-anchor="middle" font-family="Bebas Neue"
                   font-size="${44 * u}" fill="#c8c8d0">${escapeXml(labels[i] || "")}</text>`;
  });
  const titleIn = interpolate(frame, [0, 15], [0, 1], { clamp: true });
  return svg(ctx, `
    <text x="${chartLeft}" y="${150 * u}" font-family="Montserrat" font-weight="900" font-size="${72 * u}"
          fill="#ffffff" opacity="${titleIn}">${escapeXml(props.title)}</text>
    <line x1="${chartLeft}" y1="${base}" x2="${chartRight}" y2="${base}" stroke="#ffffff55" stroke-width="${3 * u}"/>
    ${bars}`, { background: "#15151b" });
}
=== graphic/tests/graphics/callout.js
// callout — road map 10 §5k 6: a circle drawing itself on (a
// stroke-dasharray draw-on) and an arrow, over a transparent background.
export const meta = {
  name: "Callout",
  durationInFrames: 90,
};

export const schema = {
  x:     { type: "number", default: 0.62, min: 0, max: 1, step: 0.01 },
  y:     { type: "number", default: 0.4,  min: 0, max: 1, step: 0.01 },
  label: { type: "string", default: "Click here first" },
  color: { type: "color",  default: "#ff3b30" },
};

export function render(frame, props, ctx) {
  const u = ctx.height / 1080;
  const cx = props.x * ctx.width;
  const cy = props.y * ctx.height;
  const r = 110 * u;
  const circumference = 2 * Math.PI * r;
  const draw = interpolate(frame, [0, 24], [0, 1], { easing: Easing.inOutCubic, clamp: true });
  const arrow = interpolate(frame, [18, 36], [0, 1], { easing: Easing.outBack, clamp: true });
  const labelIn = spring({ frame: frame - 30, fps: ctx.fps, damping: 15 });
  const ax = cx - r * 0.75;
  const ay = cy + r * 0.75;
  const tailX = ax - 260 * u;
  const tailY = ay + 200 * u;
  const hx = tailX + (ax - tailX) * arrow;
  const hy = tailY + (ay - tailY) * arrow;
  const angle = Math.atan2(ay - tailY, ax - tailX);
  const head = 34 * u;
  const p1 = `${hx - head * Math.cos(angle - 0.45)},${hy - head * Math.sin(angle - 0.45)}`;
  const p2 = `${hx - head * Math.cos(angle + 0.45)},${hy - head * Math.sin(angle + 0.45)}`;
  const stroke = 10 * u;
  return svg(ctx, `
    <circle cx="${cx}" cy="${cy}" r="${r}" fill="none" stroke="${props.color}" stroke-width="${stroke}"
            stroke-linecap="round" stroke-dasharray="${circumference}"
            stroke-dashoffset="${circumference * (1 - draw)}" transform="rotate(-90 ${cx} ${cy})"/>
    <g opacity="${arrow > 0 ? 1 : 0}">
      <line x1="${tailX}" y1="${tailY}" x2="${hx}" y2="${hy}" stroke="${props.color}" stroke-width="${stroke}"
            stroke-linecap="round"/>
      <polygon points="${hx},${hy} ${p1} ${p2}" fill="${props.color}"/>
    </g>
    <text x="${tailX}" y="${tailY + 70 * u}" text-anchor="middle" font-family="Darker Grotesque" font-weight="800"
          font-size="${64 * u}" fill="#ffffff" stroke="#000000" stroke-width="${2 * u}"
          opacity="${Math.max(0, Math.min(1, labelIn))}">${escapeXml(props.label)}</text>`);
}
