// title-card — road map 10 §5k 2: fitText on a long title over a gradient,
// with a fade in and out.
export const meta = {
  name: "Title card",
  durationInFrames: 120,
};

export const schema = {
  title:  { type: "string", default: "The Long Road to a Motion Graphic" },
  kicker: { type: "string", default: "CHAPTER ONE" },
  from:   { type: "color",  default: "#1b2a6b" },
  to:     { type: "color",  default: "#c2185b" },
};

export function render(frame, props, ctx) {
  const u = ctx.height / 1080;
  const width = ctx.width * 0.8;
  const size = fitText(props.title, width, { family: "Anton", weight: 400 }, { min: 24 * u, max: 220 * u });
  const fadeIn = interpolate(frame, [0, 18], [0, 1], { easing: Easing.inOutSine, clamp: true });
  const fadeOut = interpolate(frame, [ctx.durationInFrames - 18, ctx.durationInFrames - 1], [1, 0], { clamp: true });
  const rise = interpolate(frame, [0, 30], [40 * u, 0], { easing: Easing.outQuart, clamp: true });
  const cy = ctx.height / 2;
  return svg(ctx, `
    <defs>
      <linearGradient id="bg" x1="0" y1="0" x2="1" y2="1">
        <stop offset="0" stop-color="${props.from}"/>
        <stop offset="1" stop-color="${props.to}"/>
      </linearGradient>
    </defs>
    <rect x="0" y="0" width="${ctx.width}" height="${ctx.height}" fill="url(#bg)"/>
    <g opacity="${fadeIn * fadeOut}" transform="translate(0 ${rise})">
      <text x="${ctx.width / 2}" y="${cy - size * 0.35 - 30 * u}" text-anchor="middle" font-family="Bebas Neue"
            font-size="${48 * u}" letter-spacing="${6 * u}" fill="#ffffffcc">${escapeXml(props.kicker)}</text>
      <text x="${ctx.width / 2}" y="${cy + size * 0.45}" text-anchor="middle" font-family="Anton"
            font-size="${size}" fill="#ffffff">${escapeXml(props.title)}</text>
    </g>`);
}
// app/Sources/GraphicTemplates.swift — the graphic modules the app bundles
// as templates (road map 10's G5b): `graphic/tests/graphics/*.js`, copied
// into `Contents/Resources/GraphicTemplates/` by project.yml's "Copy Graphic
// Templates" script. Insert ▸ Graphic lists them; choosing one writes it into
// the package's `graphics/` under a free name and places a clip drawn by it.
//
// **A template's title comes from its FILE STEM, never from compiling it**:
// the menu bar is built by chrome probes that instantiate
// `AppDelegate()` with no engine work in sight, and a stem is always there.
// A missing folder lists nothing.

import Foundation

/// One bundled template: its module name (the file stem), its menu title
/// and where the file is.
struct GraphicTemplate: Equatable {
    let name: String
    let title: String
    let url: URL
}

enum GraphicTemplates {
    static let folderName = "GraphicTemplates"

    /// The folder beside `Fonts/` — `GraphicStore.manualDirectory`'s rule,
    /// so a probe that copies `Fonts/` next to itself can copy this too.
    static func directory(besideFonts fonts: URL) -> URL {
        GraphicStore.manualDirectory(besideFonts: fonts)
            .appendingPathComponent(folderName, isDirectory: true)
    }

    /// The app bundle's own.
    static var bundledDirectory: URL {
        directory(besideFonts: ProjectDocument.bundledFontsDirectory)
    }

    /// Every `*.js` in `directory` whose stem is a module name, sorted by
    /// name; `[]` when the folder is absent.
    static func list(in directory: URL) -> [GraphicTemplate] {
        let entries = (try? FileManager.default.contentsOfDirectory(
            at: directory, includingPropertiesForKeys: nil,
            options: [.skipsHiddenFiles])) ?? []
        return entries.compactMap { url -> GraphicTemplate? in
            guard url.pathExtension == "js" else { return nil }
            let name = url.deletingPathExtension().lastPathComponent
            guard GraphicStore.isModuleName(name) else { return nil }
            return GraphicTemplate(name: name, title: title(for: name), url: url)
        }.sorted { $0.name < $1.name }
    }

    /// "lower-third" → "Lower Third": split on "-", each part capitalised.
    static func title(for name: String) -> String {
        name.split(separator: "-").map { part in
            part.prefix(1).uppercased() + part.dropFirst()
        }.joined(separator: " ")
    }

    /// A file stem made a module name: lowercased; every run of anything
    /// but `a-z0-9` one "-"; "-" trimmed from both ends; at most 63
    /// characters; "graphic" when nothing is left.
    static func moduleName(from stem: String) -> String {
        var scalars: [Unicode.Scalar] = []
        var pendingDash = false
        for scalar in stem.lowercased().unicodeScalars {
            if ("a"..."z").contains(scalar) || ("0"..."9").contains(scalar) {
                if pendingDash, !scalars.isEmpty { scalars.append("-") }
                pendingDash = false
                scalars.append(scalar)
            } else {
                pendingDash = true
            }
        }
        var name = String(String.UnicodeScalarView(scalars.prefix(63)))
        while name.hasSuffix("-") { name.removeLast() }
        return name.isEmpty ? "graphic" : name
    }
}

